import type { ParsedSource } from "./source-parser";

/**
 * Vamsa Source data structure ready for database insertion
 */
export interface VamsaSource {
  id?: string;
  title: string;
  author?: string;
  publicationDate?: string;
  description?: string;
  repository?: string;
  notes?: string;
}

/**
 * Event-Source link for database insertion
 */
